# How often does the detection thread wake up when nothing is happening?# Compares `sleep(2ms)` (old) with the WinEvent-driven wait (new).$src = @'using System;using System.Threading;using System.Runtime.InteropServices;public class Wakes {    delegate void WinEventProc(IntPtr hook, uint ev, IntPtr hwnd, int idObj, int idChild, uint thread, uint time);    [DllImport("user32.dll")] static extern IntPtr SetWinEventHook(uint min, uint max, IntPtr mod, WinEventProc cb, uint pid, uint tid, uint flags);    [DllImport("kernel32.dll")] static extern IntPtr CreateEvent(IntPtr attr, bool manual, bool init, IntPtr name);    [DllImport("kernel32.dll")] static extern bool ResetEvent(IntPtr h);    [DllImport("kernel32.dll")] static extern uint WaitForSingleObject(IntPtr h, uint ms);    [DllImport("kernel32.dll")] static extern bool SetEvent(IntPtr h);    static IntPtr ev;    static WinEventProc cb = OnEvent;    static void OnEvent(IntPtr h, uint e, IntPtr w, int a, int b, uint c, uint d) { SetEvent(ev); }    // Old loop: DateTime.UtcNow.Ticks/10000 / 2 polling with a 2 ms sleep.    public static long SleepLoop(int ms, int seconds) {        long n = 0; long end = DateTime.UtcNow.Ticks/10000 + seconds * 1000;        while (DateTime.UtcNow.Ticks/10000 < end) { n++; Thread.Sleep(ms); }        return n;    }    public static long EventLoop(int ms, int seconds, out long callbacks) {        ev = CreateEvent(IntPtr.Zero, true, false, IntPtr.Zero);        long cbs = 0;        Interlocked.Increment(ref cbs);        SetWinEventHook(0x8000, 0x8001, IntPtr.Zero, cb, 0, 0, 0); // EVENT_OBJECT_CREATE..SHOW, OUTOFCONTEXT        long n = 0; long end = DateTime.UtcNow.Ticks/10000 + seconds * 1000;        while (DateTime.UtcNow.Ticks/10000 < end) { ResetEvent(ev); WaitForSingleObject(ev, (uint)ms); n++; }        callbacks = 0;        return n;    }}'@Add-Type -TypeDefinition $src -ReferencedAssemblies System.Runtime.InteropServices$s = 10$nOld = [Wakes]::SleepLoop(2, $s)$cb = 0L$nNew = [Wakes]::EventLoop(2, $s, [ref]$cb)"sleep(2ms) loop : {0} iterations in {1}s ({2} wakes/s)" -f $nOld, $s, [math]::Round($nOld / $s, 1)"event wait (2ms): {0} iterations in {1}s ({2} duration-limited waits/s; each wake = a real UI event)" -f $nNew, $s, [math]::Round($nNew / $s, 1)"ratio sleep/event = {0:N1}x" -f ($nOld / [math]::Max($nNew, 1))